-- Repaired form-template seed: 20260710054200_reseed_core_form_templates.
-- The original 2026-01 seed contained malformed JSON delimiters and is now a
-- safe historical marker. This idempotent seed preserves the intended forms.

with seed as (
  select
    (item->>'module')::public.module_type as module,
    item->>'name' as name,
    item->>'description' as description,
    item->'schema_json' as schema_json,
    coalesce((item->>'is_active')::boolean, true) as is_active
  from jsonb_array_elements($hpg_forms$[{"module":"ngo_coordination","name":"NGO Intake/Update","description":"Register or update an NGO partner with contact and jurisdiction details","schema_json":{"fields":[{"name":"legal_name","type":"text","label":"Legal Organization Name","required":true},{"name":"common_name","type":"text","label":"Common/Display Name"},{"name":"bundle","type":"select","label":"Bundle","options":["Detroit","Chicago","US","Mexican","African","Asian"]},{"name":"country","type":"text","label":"Country"},{"name":"state_province","type":"text","label":"State/Province"},{"name":"city","type":"text","label":"City"},{"name":"website","type":"url","label":"Website"},{"name":"fiscal_type","type":"select","label":"Fiscal Type","options":["model_a","model_c","other","HPG Internal Project"]},{"name":"primary_contact_name","type":"text","label":"Primary Contact Name","required":true},{"name":"primary_contact_email","type":"email","label":"Primary Contact Email","required":true},{"name":"primary_contact_phone","type":"tel","label":"Primary Contact Phone"}]},"is_active":true},{"module":"ngo_coordination","name":"Monthly NGO Check-in","description":"Record monthly status, activities, and support needs","schema_json":{"fields":[{"name":"activities_completed","type":"textarea","label":"Activities Completed This Month","required":true},{"name":"upcoming_activities","type":"textarea","label":"Planned Activities Next Month"},{"name":"blockers","type":"textarea","label":"Current Blockers or Challenges"},{"name":"support_needed","type":"textarea","label":"Support Needed from HPG"},{"name":"highlights","type":"textarea","label":"Highlights/Wins to Share"}]},"is_active":true},{"module":"ngo_coordination","name":"Document Request","description":"Request specific documents from an NGO partner","schema_json":{"fields":[{"name":"document_type","type":"select","label":"Document Type","options":["W-9","Insurance Certificate","Board Resolution","Financial Statement","Annual Report","Other"],"required":true},{"name":"description","type":"textarea","label":"Description/Instructions"},{"name":"due_date","type":"date","label":"Due Date","required":true},{"name":"external_visible","type":"checkbox","label":"Make visible to NGO portal"}]},"is_active":true},{"module":"administration","name":"Monthly VP Departmental Report","description":"Submit monthly departmental report to VP","schema_json":{"fields":[{"name":"reporting_period","type":"date","label":"Reporting Period","required":true},{"name":"key_achievements","type":"textarea","label":"Key Achievements","required":true},{"name":"challenges","type":"textarea","label":"Challenges Faced"},{"name":"budget_status","type":"select","label":"Budget Status","options":["On Track","Over Budget","Under Budget"]},{"name":"next_month_priorities","type":"textarea","label":"Next Month Priorities","required":true}]},"is_active":true},{"module":"administration","name":"Assignment creation request","description":"Request creation of a new assignment or task","schema_json":{"fields":[{"name":"assignment_title","type":"text","label":"Assignment Title","required":true},{"name":"description","type":"textarea","label":"Description","required":true},{"name":"priority","type":"select","label":"Priority","options":["Low","Medium","High","Urgent"],"required":true},{"name":"due_date","type":"date","label":"Due Date"},{"name":"assigned_to","type":"text","label":"Assigned To (User/Department)"}]},"is_active":true},{"module":"administration","name":"Policy/SOP acknowledgment","description":"Acknowledge receipt and understanding of policy or SOP","schema_json":{"fields":[{"name":"policy_name","type":"text","label":"Policy/SOP Name","required":true},{"name":"policy_version","type":"text","label":"Version"},{"name":"acknowledged","type":"checkbox","label":"I acknowledge receipt and understanding","required":true},{"name":"questions","type":"textarea","label":"Questions or Concerns"}]},"is_active":true},{"module":"operations","name":"Project kickoff","description":"Initiate a new project with kickoff details","schema_json":{"fields":[{"name":"project_name","type":"text","label":"Project Name","required":true},{"name":"project_description","type":"textarea","label":"Project Description","required":true},{"name":"start_date","type":"date","label":"Start Date","required":true},{"name":"end_date","type":"date","label":"Expected End Date"},{"name":"project_lead","type":"text","label":"Project Lead","required":true},{"name":"stakeholders","type":"textarea","label":"Key Stakeholders"}]},"is_active":true},{"module":"operations","name":"Weekly status update","description":"Submit weekly project or operational status update","schema_json":{"fields":[{"name":"week_ending","type":"date","label":"Week Ending","required":true},{"name":"completed_tasks","type":"textarea","label":"Completed Tasks","required":true},{"name":"in_progress","type":"textarea","label":"In Progress"},{"name":"blockers","type":"textarea","label":"Blockers"},{"name":"next_week_priorities","type":"textarea","label":"Next Week Priorities","required":true}]},"is_active":true},{"module":"program","name":"Monthly program activity report","description":"Report monthly program activities and outcomes","schema_json":{"fields":[{"name":"reporting_period","type":"date","label":"Reporting Period","required":true},{"name":"activities_completed","type":"textarea","label":"Activities Completed","required":true},{"name":"participants_served","type":"number","label":"Participants Served"},{"name":"outcomes","type":"textarea","label":"Key Outcomes"},{"name":"challenges","type":"textarea","label":"Challenges"},{"name":"next_month_plans","type":"textarea","label":"Next Month Plans","required":true}]},"is_active":true},{"module":"program","name":"Incident/issue report","description":"Report incidents or issues requiring attention","schema_json":{"fields":[{"name":"incident_date","type":"date","label":"Incident Date","required":true},{"name":"incident_type","type":"select","label":"Incident Type","options":["Safety","Behavioral","Program","Facility","Other"],"required":true},{"name":"description","type":"textarea","label":"Description","required":true},{"name":"severity","type":"select","label":"Severity","options":["Low","Medium","High","Critical"],"required":true},{"name":"actions_taken","type":"textarea","label":"Actions Taken"},{"name":"follow_up_required","type":"checkbox","label":"Follow-up Required"}]},"is_active":true},{"module":"curriculum","name":"Curriculum change request","description":"Request changes to existing curriculum","schema_json":{"fields":[{"name":"curriculum_name","type":"text","label":"Curriculum Name","required":true},{"name":"change_type","type":"select","label":"Change Type","options":["Content Update","New Module","Removal","Restructure"],"required":true},{"name":"rationale","type":"textarea","label":"Rationale for Change","required":true},{"name":"proposed_changes","type":"textarea","label":"Proposed Changes","required":true},{"name":"impact_assessment","type":"textarea","label":"Impact Assessment"}]},"is_active":true},{"module":"curriculum","name":"Curriculum publishing checklist","description":"Checklist for publishing new or updated curriculum","schema_json":{"fields":[{"name":"curriculum_name","type":"text","label":"Curriculum Name","required":true},{"name":"version","type":"text","label":"Version Number","required":true},{"name":"review_completed","type":"checkbox","label":"Content Review Completed"},{"name":"approvals_obtained","type":"checkbox","label":"All Approvals Obtained"},{"name":"formatting_verified","type":"checkbox","label":"Formatting Verified"},{"name":"accessibility_checked","type":"checkbox","label":"Accessibility Checked"},{"name":"ready_to_publish","type":"checkbox","label":"Ready to Publish","required":true}]},"is_active":true}]$hpg_forms$::jsonb) as seeded(item)
)
insert into public.form_templates (module, name, description, schema_json, is_active)
select module, name, description, schema_json, is_active
from seed
on conflict (module, name) do update set
  description = excluded.description,
  schema_json = excluded.schema_json,
  is_active = excluded.is_active,
  updated_at = now();
